// Ported verbatim from android RiddleMatcherTest.kt (feat/riddle-pack), plus the cross-language golden check
// against scripts/riddles/riddle_norm.py (golden.json is generated by gen_golden.py from the Python reference).
import test from 'node:test'
import assert from 'node:assert/strict'
import * as M from '../../src/components/puzzles/riddles/riddleMatcher.js'
import { golden, riddle } from './support.mjs'

const ok = (input, answer, ...alt) => M.isCorrect(input, riddle(answer, ...alt))

test('ignoresCaseWhitespacePunctuationAndAccents', () => {
  assert.ok(ok('  CLOCK!! ', 'clock'))
  assert.ok(ok('Cl-ock', 'clock')) // a stray hyphen or space inside the word is forgiven
  assert.ok(ok('cafe', 'café'))
  assert.ok(ok('Café', 'cafe'))
})

test('ignoresLeadingArticlesAndFillers', () => {
  assert.ok(ok('a clock', 'clock'))
  assert.ok(ok('An Elephant', 'elephant'))
  assert.ok(ok('the moon', 'moon'))
  assert.ok(ok("it's a clock", 'clock'))
  assert.ok(ok('It is the clock.', 'clock'))
  assert.ok(ok('I think it is a clock', 'clock'))
  assert.ok(ok('clock', 'a clock'))
})

test('acceptsSimplePluralsBothWays', () => {
  assert.ok(ok('clocks', 'clock'))
  assert.ok(ok('clock', 'clocks'))
  assert.ok(ok('cities', 'city'))
  assert.ok(ok('boxes', 'box'))
  assert.ok(ok('leaves', 'leaf'))
  assert.ok(ok('knives', 'knife'))
  assert.ok(ok('glasses', 'glass'))
  assert.ok(ok('deck of card', 'deck of cards'))
})

test('acceptsAlternates', () => {
  assert.ok(ok('watch', 'clock', 'watch'))
  assert.ok(ok('The Watches', 'clock', 'watch'))
})

test('rejectsWrongEmptyAndStopWordOnlyAnswers', () => {
  assert.ok(!ok('', 'clock'))
  assert.ok(!ok('   ', 'clock'))
  assert.ok(!ok('!!!', 'clock'))
  assert.ok(!ok('the', 'clock'))
  assert.ok(!ok('a', 'clock'))
  assert.ok(!ok('cloak', 'clock')) // 5 letters: no typo tolerance
  assert.ok(!ok('oak', 'tree')) // no synonym or category guessing
  assert.ok(!ok('tree', 'oak'))
})

test('shortAnswersAndNumbersMustBeExact', () => {
  assert.ok(!ok('12', '13', 'thirteen'))
  assert.ok(!ok('1943', '194'))
  assert.ok(ok('thirteen', '13', 'thirteen'))
  assert.ok(!ok('monk', 'monkey')) // missing letters are not tolerated on 6-letter words
})

test('toleratesOneTypoOnLongAnswersOnly', () => {
  assert.ok(ok('elephnat', 'elephant')) // swapped neighbours count as one edit
  assert.ok(ok('elephnt', 'elephant'))
  assert.ok(!ok('elefant', 'elephant')) // two edits
  assert.ok(ok('telescpe', 'telescope'))
  assert.ok(!ok('telscpe', 'telescope')) // two edits on a 9-letter word
  assert.ok(ok('thermomter', 'thermometer'))
  assert.ok(ok('thermometr', 'thermometer'))
})

test('singleLetterAnswersGetNoTypoTolerance', () => {
  assert.ok(!ok('the letter R', 'the letter M', 'm'))
  assert.ok(ok('letter m', 'the letter M', 'm'))
})

test('extraSpacesInsideCompoundWordsAreForgiven', () => {
  assert.ok(ok('tea pot', 'teapot'))
  assert.ok(ok('teapot', 'tea pot'))
  assert.ok(ok('book keeper', 'bookkeeper'))
})

test('editDistanceIsCorrect', () => {
  assert.equal(M.editDistance('abc', 'abc'), 0)
  assert.equal(M.editDistance('abc', 'abd'), 1)
  assert.equal(M.editDistance('abc', 'abcd'), 1)
  assert.equal(M.editDistance('kitten', 'sitting'), 3)
  assert.equal(M.editDistance('', 'abc'), 3)
  assert.equal(M.editDistance('ab', 'ba'), 1)
})

test('locale-independent lower-casing (Kotlin Turkish-locale case): PIANO / ICE', () => {
  // JS toLowerCase is locale-independent; this pins that no toLocaleLowerCase slips in.
  const orig = String.prototype.toLocaleLowerCase
  String.prototype.toLocaleLowerCase = function () { return this.toLowerCase().replace(/i/g, 'ı') } // simulate tr-TR
  try {
    assert.ok(ok('PIANO', 'piano'))
    assert.ok(ok('ICE', 'ice'))
  } finally { String.prototype.toLocaleLowerCase = orig }
})

test('typoBudget tiers: 0 below 7 letters / digits / single-letter tokens, 1 for 7-11, 2 for 12+', () => {
  assert.equal(M.typoBudget('clock'), 0)
  assert.equal(M.typoBudget('monkey'), 0)
  assert.equal(M.typoBudget('elephant'), 1)
  assert.equal(M.typoBudget('12345678'), 0)
  assert.equal(M.typoBudget('the letter M'), 0)
  assert.equal(M.typoBudget('refrigerators'), 2)
})

// ---- cross-language agreement with scripts/riddles/riddle_norm.py ---------------------------------------------

test('golden: JS normalise() equals Python norm() on every case (all accepted answers + edge strings)', () => {
  assert.ok(golden.normCases.length >= 300)
  for (const c of golden.normCases) {
    assert.deepEqual(M.normalize(c.s), c.tokens, JSON.stringify(c.s))
  }
})

test('golden: JS variants() equals Python variants() for every token', () => {
  for (const c of golden.normCases) {
    c.tokens.forEach((t, i) => assert.deepEqual([...M.variants(t)].sort(), c.variants[i], `${c.s} / ${t}`))
  }
})

test('golden: JS same() equals Python same() on every pair (derived forms, cross-riddle, edge strings)', () => {
  assert.ok(golden.pairs.length > 3000)
  for (const p of golden.pairs) assert.equal(M.same(p.a, p.b), p.same, `${JSON.stringify(p.a)} vs ${JSON.stringify(p.b)}`)
})

test('golden: every one of the 300 primary answers (and every alternate) is accepted as typed', () => {
  assert.ok(golden.accepted.length >= 300)
  for (const f of golden.accepted) assert.ok(M.matchesForm(f, f), f)
})
